#include "mgt_cuda/mlp_batch_norm_forward.cuh"
#include "mgt_cuda/allreduce_nccl.cuh"
#include "batch_norm_activation.cuh"
#include "sync_batch_norm.cuh"
#include <algorithm>
namespace mgt_cuda { namespace {
constexpr unsigned T=256;
__host__ __device__ std::uint64_t RB(CudaMlpShape s){return 2ULL*(static_cast<std::uint64_t>(s.hd2)*s.hd2+s.hd2);}__host__ __device__ std::uint64_t IB(CudaMlpShape s){return static_cast<std::uint64_t>(s.state_len)*s.state_value_pad*s.hd1;}__host__ __device__ std::uint64_t HW(CudaMlpShape s){return IB(s)+s.hd1;}__host__ __device__ std::uint64_t HB(CudaMlpShape s){return HW(s)+static_cast<std::uint64_t>(s.hd1)*s.hd2;}__host__ __device__ std::uint64_t R0(CudaMlpShape s){return HB(s)+s.hd2;}__host__ __device__ std::uint64_t OW(CudaMlpShape s){return R0(s)+static_cast<std::uint64_t>(s.residual_blocks)*RB(s);}__host__ __device__ std::uint64_t OB(CudaMlpShape s){return OW(s)+static_cast<std::uint64_t>(s.hd2)*s.output_dim;}__host__ __device__ std::uint64_t F1W(CudaMlpShape s,unsigned b){return R0(s)+static_cast<std::uint64_t>(b)*RB(s);}__host__ __device__ std::uint64_t F1B(CudaMlpShape s,unsigned b){return F1W(s,b)+static_cast<std::uint64_t>(s.hd2)*s.hd2;}__host__ __device__ std::uint64_t F2W(CudaMlpShape s,unsigned b){return F1B(s,b)+s.hd2;}__host__ __device__ std::uint64_t F2B(CudaMlpShape s,unsigned b){return F2W(s,b)+static_cast<std::uint64_t>(s.hd2)*s.hd2;}
__global__ void Input(CudaMlpShape s,unsigned logical,const float*w,const mgt::TrainStateStorage*states,unsigned rows,float*out){unsigned q=blockIdx.x*blockDim.x+threadIdx.x;if(q>=rows*s.hd1)return;unsigned r=q/s.hd1,h=q-r*s.hd1;if(h>=logical){out[q]=0;return;}float v=w[IB(s)+h];for(unsigned p=0;p<s.state_len;p++)v+=w[(static_cast<std::uint64_t>(p)*s.state_value_pad+states[r].v[p])*s.hd1+h];out[q]=v;}
__global__ void Bias(float*x,const float*b,unsigned rows,unsigned stride,unsigned logical){unsigned q=blockIdx.x*blockDim.x+threadIdx.x;if(q>=rows*stride)return;unsigned c=q%stride;x[q]=c<logical?x[q]+b[c]:0;}
__global__ void OutputBias(float*x,const float*b,unsigned rows,unsigned cols){unsigned q=blockIdx.x*blockDim.x+threadIdx.x;if(q<rows*cols)x[q]+=b[q%cols];}
__global__ void OutputLossGrad(const float*outputs,const float*labels,unsigned count,unsigned cols,float scale,float*loss,float*dy,float*bias_grad){unsigned q=blockIdx.x*blockDim.x+threadIdx.x;if(q>=count)return;float d=outputs[q]-labels[q];dy[q]=2.0f*d*scale;atomicAdd(loss,d*d*scale);atomicAdd(bias_grad+q%cols,dy[q]);}
__global__ void ScalarOutputLossGrad(const float*outputs,const float*labels,unsigned rows,float scale,float*loss,float*dy,float*bias_grad){__shared__ float sl[T],sb[T];unsigned r=blockIdx.x*blockDim.x+threadIdx.x;float l=0,g=0;if(r<rows){float d=outputs[r]-labels[r];g=2.0f*d*scale;l=d*d*scale;dy[r]=g;}sl[threadIdx.x]=l;sb[threadIdx.x]=g;__syncthreads();for(unsigned d=blockDim.x/2;d;d>>=1){if(threadIdx.x<d){sl[threadIdx.x]+=sl[threadIdx.x+d];sb[threadIdx.x]+=sb[threadIdx.x+d];}__syncthreads();}if(threadIdx.x==0){atomicAdd(loss,sl[0]);atomicAdd(bias_grad,sb[0]);}}
__global__ void ScalarOutputInputGrad(const float*dy,const float*w,unsigned rows,unsigned hd2,float*d_final){unsigned q=blockIdx.x*blockDim.x+threadIdx.x;if(q<rows*hd2)d_final[q]=dy[q/hd2]*w[q%hd2];}
__global__ void ColumnSum(const float*x,unsigned rows,unsigned logical,unsigned stride,float*out){unsigned c=blockIdx.x;if(c>=stride)return;if(c>=logical){if(threadIdx.x==0)out[c]=0;return;}__shared__ float v[T];float z=0;for(unsigned r=threadIdx.x;r<rows;r+=T)z+=x[static_cast<std::uint64_t>(r)*stride+c];v[threadIdx.x]=z;__syncthreads();for(unsigned d=T/2;d;d>>=1){if(threadIdx.x<d)v[threadIdx.x]+=v[threadIdx.x+d];__syncthreads();}if(threadIdx.x==0)out[c]=v[0];}
__global__ void AddInPlace(float*x,const float*y,std::uint64_t n){std::uint64_t q=static_cast<std::uint64_t>(blockIdx.x)*blockDim.x+threadIdx.x;if(q<n)x[q]+=y[q];}
mgt::Status Gemm(cublasHandle_t h,const float*a,const float*b,float*c,unsigned m,unsigned n,unsigned k){float alpha=1,beta=0;return cublasSgemm(h,CUBLAS_OP_N,CUBLAS_OP_N,n,m,k,&alpha,b,n,a,k,&beta,c,n)==CUBLAS_STATUS_SUCCESS?mgt::Status::kOk:mgt::Status::kCudaFailure;}
bool launch(){return cudaPeekAtLastError()==cudaSuccess;}
}
std::uint64_t MlpBatchNormForwardWorkspaceFloats(const CudaMlpShape&s,const mgt::BatchNormTrainingPlan&p,std::uint32_t rows){if(!rows||p.workspace_floats==0)return 0;return static_cast<std::uint64_t>(rows)*(s.hd1+(2ULL*s.residual_blocks+1ULL)*s.hd2)+p.workspace_floats;}
mgt::Status LaunchMlpBatchNormForward(const CudaMlpShape&s,std::uint32_t lh1,std::uint32_t lh2,const float*w,float*aff,float*run,const mgt::TrainStateStorage*states,std::uint32_t lr,std::uint32_t gr,float*out,float*base,std::uint64_t count,const mgt::BatchNormTrainingPlan&p,NcclRankContext*ctx,cublasHandle_t blas,cudaStream_t st){if(ValidateCudaMlpShape(s)!=mgt::Status::kOk||!lh1||!lh2||lh1>s.hd1||lh2>s.hd2||!w||!aff||!run||!states||!lr||gr<lr||!out||!base||!ctx||!blas||p.sites.size()!=2+2*s.residual_blocks||count<MlpBatchNormForwardWorkspaceFloats(s,p,lr))return mgt::Status::kInvalidConfig;if(cublasSetStream(blas,st)!=CUBLAS_STATUS_SUCCESS)return mgt::Status::kCudaFailure;const std::uint64_t bh2=static_cast<std::uint64_t>(lr)*s.hd2;float*a1=base;base+=static_cast<std::uint64_t>(lr)*s.hd1;float*block_inputs=base;base+=static_cast<std::uint64_t>(s.residual_blocks+1U)*bh2;float*fc1_activations=base;base+=static_cast<std::uint64_t>(s.residual_blocks)*bh2;float*cur=block_inputs;float*f1=nullptr;float*f2=nullptr;float*bn=base;float*scratch=bn+p.reduction_offset;auto site=[&](unsigned i,float*x){const auto&q=p.sites[i];return LaunchStridedSyncBatchNormForward(x,lr,gr,q.logical_features,q.physical_stride,aff+q.affine_offset,aff+p.logical_feature_count+q.affine_offset,run+q.running_offset,run+p.logical_feature_count+q.running_offset,.1f,1e-5f,x,bn+q.mean_offset,bn+q.inv_std_offset,bn+q.normalized_offset,scratch,ctx,st);};unsigned blocks1=(lr*s.hd1+T-1)/T,blocks2=(lr*s.hd2+T-1)/T;Input<<<blocks1,T,0,st>>>(s,lh1,w,states,lr,a1);if(!launch()||site(0,a1)!=mgt::Status::kOk||LaunchBatchNormReluForward(a1,static_cast<std::uint64_t>(lr)*s.hd1,st)!=mgt::Status::kOk)return mgt::Status::kCudaFailure;if(Gemm(blas,a1,w+HW(s),cur,lr,s.hd2,s.hd1)!=mgt::Status::kOk)return mgt::Status::kCudaFailure;Bias<<<blocks2,T,0,st>>>(cur,w+HB(s),lr,s.hd2,lh2);if(!launch()||site(1,cur)!=mgt::Status::kOk||LaunchBatchNormReluForward(cur,static_cast<std::uint64_t>(lr)*s.hd2,st)!=mgt::Status::kOk)return mgt::Status::kCudaFailure;for(unsigned b=0;b<s.residual_blocks;b++){cur=block_inputs+static_cast<std::uint64_t>(b)*bh2;f1=fc1_activations+static_cast<std::uint64_t>(b)*bh2;f2=block_inputs+static_cast<std::uint64_t>(b+1U)*bh2;if(Gemm(blas,cur,w+F1W(s,b),f1,lr,s.hd2,s.hd2)!=mgt::Status::kOk)return mgt::Status::kCudaFailure;Bias<<<blocks2,T,0,st>>>(f1,w+F1B(s,b),lr,s.hd2,lh2);if(!launch()||site(2+2*b,f1)!=mgt::Status::kOk||LaunchBatchNormReluForward(f1,static_cast<std::uint64_t>(lr)*s.hd2,st)!=mgt::Status::kOk)return mgt::Status::kCudaFailure;if(Gemm(blas,f1,w+F2W(s,b),f2,lr,s.hd2,s.hd2)!=mgt::Status::kOk)return mgt::Status::kCudaFailure;Bias<<<blocks2,T,0,st>>>(f2,w+F2B(s,b),lr,s.hd2,lh2);if(!launch()||site(3+2*b,f2)!=mgt::Status::kOk||LaunchBatchNormResidualReluForward(cur,f2,static_cast<std::uint64_t>(lr)*s.hd2,st)!=mgt::Status::kOk)return mgt::Status::kCudaFailure;}cur=block_inputs+static_cast<std::uint64_t>(s.residual_blocks)*bh2;if(Gemm(blas,cur,w+OW(s),out,lr,s.output_dim,s.hd2)!=mgt::Status::kOk)return mgt::Status::kCudaFailure;unsigned bo=(lr*s.output_dim+T-1)/T;OutputBias<<<bo,T,0,st>>>(out,w+OB(s),lr,s.output_dim);return launch()?mgt::Status::kOk:mgt::Status::kCudaFailure;}
mgt::Status LaunchMlpBatchNormOutputLossGrad(const CudaMlpShape&s,const float*w,const float*labels,const float*outputs,const float*final_activation,std::uint32_t lr,std::uint32_t gr,float*loss,float*weight_grad,float*dy,float*d_final,NcclRankContext*ctx,cublasHandle_t blas,cudaStream_t st){if(ValidateCudaMlpShape(s)!=mgt::Status::kOk||!w||!labels||!outputs||!final_activation||!lr||gr<lr||!loss||!weight_grad||!dy||!d_final||!ctx||!blas)return mgt::Status::kInvalidConfig;if(cublasSetStream(blas,st)!=CUBLAS_STATUS_SUCCESS)return mgt::Status::kCudaFailure;const std::uint64_t wc=static_cast<std::uint64_t>(s.hd2)*s.output_dim,pc=wc+s.output_dim;if(cudaMemsetAsync(loss,0,sizeof(float),st)!=cudaSuccess||cudaMemsetAsync(weight_grad+OW(s),0,pc*sizeof(float),st)!=cudaSuccess)return mgt::Status::kCudaFailure;unsigned count=lr*s.output_dim,blocks=(count+T-1)/T;float alpha=1,beta=0;if(s.output_dim==1){ScalarOutputLossGrad<<<(lr+T-1)/T,T,0,st>>>(outputs,labels,lr,1.0f/static_cast<float>(gr),loss,dy,weight_grad+OB(s));if(!launch()||cublasSgemv(blas,CUBLAS_OP_N,s.hd2,lr,&alpha,final_activation,s.hd2,dy,1,&beta,weight_grad+OW(s),1)!=CUBLAS_STATUS_SUCCESS)return mgt::Status::kCudaFailure;ScalarOutputInputGrad<<<(lr*s.hd2+T-1)/T,T,0,st>>>(dy,w+OW(s),lr,s.hd2,d_final);if(!launch())return mgt::Status::kCudaFailure;}else{OutputLossGrad<<<blocks,T,0,st>>>(outputs,labels,count,s.output_dim,1.0f/(static_cast<float>(gr)*s.output_dim),loss,dy,weight_grad+OB(s));if(!launch()||cublasSgemm(blas,CUBLAS_OP_N,CUBLAS_OP_T,s.output_dim,s.hd2,lr,&alpha,dy,s.output_dim,final_activation,s.hd2,&beta,weight_grad+OW(s),s.output_dim)!=CUBLAS_STATUS_SUCCESS||cublasSgemm(blas,CUBLAS_OP_T,CUBLAS_OP_N,s.hd2,lr,s.output_dim,&alpha,w+OW(s),s.output_dim,dy,s.output_dim,&beta,d_final,s.hd2)!=CUBLAS_STATUS_SUCCESS)return mgt::Status::kCudaFailure;}if(NcclAllreduceSumFloat(weight_grad+OW(s),pc,ctx,st)!=mgt::Status::kOk||NcclAllreduceSumFloat(loss,1,ctx,st)!=mgt::Status::kOk)return mgt::Status::kCudaFailure;return mgt::Status::kOk;}
static mgt::Status ResidualFc2Impl(const CudaMlpShape&s,const float*w,const float*aff,std::uint32_t b,std::uint32_t lr,std::uint32_t gr,float*fw,const mgt::BatchNormTrainingPlan&p,float*block_grad,float*weight_grad,float*affine_grad,float*d_fc1,float*d_residual,NcclRankContext*ctx,cublasHandle_t blas,cudaStream_t st,bool reduce){if(ValidateCudaMlpShape(s)!=mgt::Status::kOk||!w||!aff||b>=s.residual_blocks||!lr||gr<lr||!fw||p.sites.size()!=2+2*s.residual_blocks||!block_grad||!weight_grad||!affine_grad||!d_fc1||!d_residual||!ctx||!blas)return mgt::Status::kInvalidConfig;if(cublasSetStream(blas,st)!=CUBLAS_STATUS_SUCCESS)return mgt::Status::kCudaFailure;const std::uint64_t bh2=static_cast<std::uint64_t>(lr)*s.hd2;float*block_inputs=fw+static_cast<std::uint64_t>(lr)*s.hd1;float*fc1_activations=block_inputs+static_cast<std::uint64_t>(s.residual_blocks+1U)*bh2;float*bn=fc1_activations+static_cast<std::uint64_t>(s.residual_blocks)*bh2;float*activated=block_inputs+static_cast<std::uint64_t>(b+1U)*bh2;float*fc1=fc1_activations+static_cast<std::uint64_t>(b)*bh2;const auto&q=p.sites[3+2*b];if(LaunchBatchNormResidualReluBackward(activated,block_grad,block_grad,d_residual,bh2,st)!=mgt::Status::kOk||LaunchStridedSyncBatchNormBackward(block_grad,lr,gr,q.logical_features,q.physical_stride,aff+q.affine_offset,bn+q.inv_std_offset,bn+q.normalized_offset,block_grad,affine_grad+q.affine_offset,affine_grad+p.logical_feature_count+q.affine_offset,bn+p.reduction_offset,ctx,st)!=mgt::Status::kOk)return mgt::Status::kCudaFailure;const std::uint64_t wc=static_cast<std::uint64_t>(s.hd2)*s.hd2,pc=wc+s.hd2;if(cudaMemsetAsync(weight_grad+F2W(s,b),0,pc*sizeof(float),st)!=cudaSuccess)return mgt::Status::kCudaFailure;float alpha=1,beta=0;if(cublasSgemm(blas,CUBLAS_OP_N,CUBLAS_OP_T,s.hd2,s.hd2,lr,&alpha,block_grad,s.hd2,fc1,s.hd2,&beta,weight_grad+F2W(s,b),s.hd2)!=CUBLAS_STATUS_SUCCESS||cublasSgemm(blas,CUBLAS_OP_T,CUBLAS_OP_N,s.hd2,lr,s.hd2,&alpha,w+F2W(s,b),s.hd2,block_grad,s.hd2,&beta,d_fc1,s.hd2)!=CUBLAS_STATUS_SUCCESS)return mgt::Status::kCudaFailure;ColumnSum<<<s.hd2,T,0,st>>>(block_grad,lr,q.logical_features,s.hd2,weight_grad+F2B(s,b));if(!launch()||(reduce&&NcclAllreduceSumFloat(weight_grad+F2W(s,b),pc,ctx,st)!=mgt::Status::kOk))return mgt::Status::kCudaFailure;return mgt::Status::kOk;}
mgt::Status LaunchMlpBatchNormResidualFc2Backward(const CudaMlpShape&s,const float*w,const float*aff,std::uint32_t b,std::uint32_t lr,std::uint32_t gr,float*fw,const mgt::BatchNormTrainingPlan&p,float*block_grad,float*weight_grad,float*affine_grad,float*d_fc1,float*d_residual,NcclRankContext*ctx,cublasHandle_t blas,cudaStream_t st){return ResidualFc2Impl(s,w,aff,b,lr,gr,fw,p,block_grad,weight_grad,affine_grad,d_fc1,d_residual,ctx,blas,st,true);}
static mgt::Status ResidualFc1Impl(const CudaMlpShape&s,const float*w,const float*aff,std::uint32_t b,std::uint32_t lr,std::uint32_t gr,float*fw,const mgt::BatchNormTrainingPlan&p,float*d_fc1,float*weight_grad,float*affine_grad,const float*d_residual,float*block_grad,NcclRankContext*ctx,cublasHandle_t blas,cudaStream_t st){const std::uint64_t bh2=static_cast<std::uint64_t>(lr)*s.hd2;float*block_inputs=fw+static_cast<std::uint64_t>(lr)*s.hd1;float*fc1_activations=block_inputs+static_cast<std::uint64_t>(s.residual_blocks+1U)*bh2;float*bn=fc1_activations+static_cast<std::uint64_t>(s.residual_blocks)*bh2;float*activated=fc1_activations+static_cast<std::uint64_t>(b)*bh2;float*input=block_inputs+static_cast<std::uint64_t>(b)*bh2;const auto&q=p.sites[2+2*b];if(LaunchBatchNormReluBackward(activated,d_fc1,d_fc1,bh2,st)!=mgt::Status::kOk||LaunchStridedSyncBatchNormBackward(d_fc1,lr,gr,q.logical_features,q.physical_stride,aff+q.affine_offset,bn+q.inv_std_offset,bn+q.normalized_offset,d_fc1,affine_grad+q.affine_offset,affine_grad+p.logical_feature_count+q.affine_offset,bn+p.reduction_offset,ctx,st)!=mgt::Status::kOk)return mgt::Status::kCudaFailure;const std::uint64_t wc=static_cast<std::uint64_t>(s.hd2)*s.hd2,pc=wc+s.hd2;if(cudaMemsetAsync(weight_grad+F1W(s,b),0,pc*sizeof(float),st)!=cudaSuccess)return mgt::Status::kCudaFailure;float alpha=1,beta=0;if(cublasSgemm(blas,CUBLAS_OP_N,CUBLAS_OP_T,s.hd2,s.hd2,lr,&alpha,d_fc1,s.hd2,input,s.hd2,&beta,weight_grad+F1W(s,b),s.hd2)!=CUBLAS_STATUS_SUCCESS||cublasSgemm(blas,CUBLAS_OP_T,CUBLAS_OP_N,s.hd2,lr,s.hd2,&alpha,w+F1W(s,b),s.hd2,d_fc1,s.hd2,&beta,block_grad,s.hd2)!=CUBLAS_STATUS_SUCCESS)return mgt::Status::kCudaFailure;ColumnSum<<<s.hd2,T,0,st>>>(d_fc1,lr,q.logical_features,s.hd2,weight_grad+F1B(s,b));AddInPlace<<<static_cast<unsigned>((bh2+T-1)/T),T,0,st>>>(block_grad,d_residual,bh2);return launch()?mgt::Status::kOk:mgt::Status::kCudaFailure;}
mgt::Status LaunchMlpBatchNormResidualStackBackward(const CudaMlpShape&s,const float*w,const float*aff,std::uint32_t lr,std::uint32_t gr,float*fw,const mgt::BatchNormTrainingPlan&p,float*block_grad,float*weight_grad,float*affine_grad,float*d_fc1,float*d_residual,NcclRankContext*ctx,cublasHandle_t blas,cudaStream_t st){if(ValidateCudaMlpShape(s)!=mgt::Status::kOk||!w||!aff||!lr||gr<lr||!fw||p.sites.size()!=2+2*s.residual_blocks||!block_grad||!weight_grad||!affine_grad||!d_fc1||!d_residual||!ctx||!blas)return mgt::Status::kInvalidConfig;for(std::uint32_t b=s.residual_blocks;b-->0;){auto z=ResidualFc2Impl(s,w,aff,b,lr,gr,fw,p,block_grad,weight_grad,affine_grad,d_fc1,d_residual,ctx,blas,st,false);if(z!=mgt::Status::kOk)return z;z=ResidualFc1Impl(s,w,aff,b,lr,gr,fw,p,d_fc1,weight_grad,affine_grad,d_residual,block_grad,ctx,blas,st);if(z!=mgt::Status::kOk)return z;}return NcclAllreduceSumFloat(weight_grad+R0(s),OW(s)-R0(s),ctx,st);}}